public class DefaultTypeResolverBuilder_useForType_TriageGen0Test {

    private TypeFactory typeFactory;

    @Before
    public void setup() {
        typeFactory = TypeFactory.defaultInstance();
    }

    /**
     * Helper to create a builder with specific DefaultTyping
     */
    private BasicTypeResolverBuilder createBuilder(DefaultTyping typing) {
        return new BasicTypeResolverBuilder(typing, null, null);
    }

    @Test
    public void testUseForType_JAVA_LANG_OBJECT_Case() {
        // Default case (JAVA_LANG_OBJECT)
        BasicTypeResolverBuilder builder = createBuilder(DefaultTyping.JAVA_LANG_OBJECT);

        JavaType objType = typeFactory.constructType(Object.class);
        JavaType stringType = typeFactory.constructType(String.class);

        assertTrue("Object should return true for JAVA_LANG_OBJECT", builder.useForType(objType));
        assertFalse("String should return false for JAVA_LANG_OBJECT", builder.useForType(stringType));
    }

    @Test
    public void testUseForType_NON_CONCRETE_AND_ARRAYS_Case() {
        // NON_CONCRETE_AND_ARRAYS falls through to OBJECT_AND_NON_CONCRETE
        BasicTypeResolverBuilder builder = createBuilder(DefaultTyping.NON_CONCRETE_AND_ARRAYS);

        // Test Array of Reference Types (e.g., Object[])
        JavaType arrayType = typeFactory.constructType(Object[].class);
        assertTrue(builder.useForType(arrayType));

        // Test Array of Concrete Types (e.g., String[]) -> should return false because String is concrete and not Object
        JavaType stringArrayType = typeFactory.constructType(String[].class);
        assertFalse(builder.useForType(stringArrayType));

        // Test Array of Reference Types that resolves to Object
        // Since NON_CONCRETE_AND_ARRAYS strips array layers via getContentType()
        // and then OBJECT_AND_NON_CONCRETE strips reference layers via getReferencedType()
        JavaType complexType = typeFactory.constructType(java.util.Optional<Object[]>.class);
        // Optional -> Object[] -> Object
        assertTrue(builder.useForType(complexType));
    }

    @Test
    public void testUseForType_OBJECT_AND_NON_CONCRETE_Case() {
        BasicTypeResolverBuilder builder = createBuilder(DefaultTyping.EVERYTHING); // Includes OBJECT_AND_NON_CONCRETE

        // Case: isJavaLangObject
        assertTrue(builder.useForType(typeFactory.constructType(Object.class)));

        // Case: !isConcrete && !TreeNode
        // We need a non-concrete type that is not a TreeNode. 
        // Interface is non-concrete.
        assertTrue(builder.useForType(typeFactory.constructType(java.util.List.class)));

        // Case: isConcrete (e.g., String) -> should be false
        assertFalse(builder.useForType(typeFactory.constructType(String.class)));

        // Case: isTreeNode (simulated via Mockito since we can't easily extend TreeNode in a way that satisfies isAssignableFrom)
        JavaType treeNodeType = Mockito.mock(JavaType.class);
        when(treeNodeType.isReferenceType()).thenReturn(false);
        when(treeNodeType.isJavaLangObject()).thenReturn(false);
        when(treeNodeType.isConcrete()).thenReturn(false);
        when(treeNodeType.getRawClass()).thenReturn(com.fasterxml.jackson.databind.node.TreeNode.class);

        assertFalse("TreeNode should return false", builder.useForType(treeNodeType));
    }

    @Test
    public void testUseForType_NON_FINAL_Case() {
        // NON_FINAL logic: strips array, then strips reference, then checks !isFinal && !isTreeNode
        BasicTypeResolverBuilder builder = createBuilder(DefaultTyping.NON_FINAL);

        // Interface is not final and not TreeNode
        assertTrue(builder.useForType(typeFactory.constructType(java.util.Map.class)));

        // Final class (String) should return false
        assertFalse(builder.useForType(typeFactory.constructType(String.class)));

        // Array of non-final types
        JavaType arrayType = typeFactory.constructType(java.util.List[].class);
        assertTrue(builder.useForType(arrayType));

        // TreeNode-like class (not final but is TreeNode)
        JavaType treeNodeType = Mockito.mock(JavaType.class);
        when(treeNodeType.isArrayType()).thenReturn(false);
        when(treeNodeType.isReferenceType()).thenReturn(false);
        when(treeNodeType.isFinal()).thenReturn(false);
        when(treeNodeType.getRawClass()).thenReturn(com.fasterxml.jackson.databind.node.TreeNode.class);

        assertFalse("TreeNode should return false for NON_FINAL", builder.useForType(treeNodeType));
    }

    @Test
    public void testUseForType_ReferenceTypeStripping() {
        BasicTypeResolverBuilder builder = createBuilder(DefaultTyping.OBJECT_AND_NON_CONCRETE);

        // Test deep reference stripping: Optional<List<String>>
        // 1. Optional.class (Reference) -> getReferencedType() -> List.class
        // 2. List.class (Reference/Interface) -> getReferencedType() -> String.class
        // 3. String.class (Concrete) -> return false
        JavaType deepType = typeFactory.constructType(java.util.Optional.class); 
        // Note: In a real Jackson environment, Optional.getReferencedType() returns List.class
        // We mock the behavior to ensure the while loop logic is covered.

        JavaType mockType = Mockito.mock(JavaType.class);
        JavaType refType = Mockito.mock(JavaType.class);
        JavaType concreteType = Mockito.mock(JavaType.class);

        when(mockType.isReferenceType()).thenReturn(true);
        when(mockType.getReferencedType()).thenReturn(refType);

        when(refType.isReferenceType()).thenReturn(true);
        when(refType.getReferencedType()).thenReturn(concreteType);

        when(concreteType.isReferenceType()).thenReturn(false);
        when(concreteType.isJavaLangObject()).thenReturn(false);
        when(concreteType.isConcrete()).thenReturn(true);

        assertFalse(builder.useForType(mockType));
    }
}
